@prefix cdi: <http://ddialliance.org/Specification/DDI-CDI/1.0/RDF/> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode <https://example.org/agent-data-pipeline> ;
            sh:resultMessage "A DDI-CDI ProcessingAgent may specify cdi:operatesOn (ProductionEnvironment)" ;
            sh:resultPath cdi:operatesOn ;
            sh:resultSeverity sh:Info ;
            sh:sourceConstraintComponent sh:OrConstraintComponent ;
            sh:sourceShape [ sh:message "A DDI-CDI ProcessingAgent may specify cdi:operatesOn (ProductionEnvironment)" ;
                    sh:or ( [ sh:nodeKind sh:IRI ] [ sh:nodeKind sh:BlankNode ] ) ;
                    sh:path cdi:operatesOn ;
                    sh:severity sh:Info ] ;
            sh:value 42 ] .

@prefix cdi: <http://ddialliance.org/Specification/DDI-CDI/1.0/RDF/> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode <https://example.org/agent-data-pipeline> ;
            sh:resultMessage "A DDI-CDI ProcessingAgent should specify at least one activity it performs" ;
            sh:resultPath cdi:performs ;
            sh:resultSeverity sh:Warning ;
            sh:sourceConstraintComponent sh:OrConstraintComponent ;
            sh:sourceShape [ sh:message "A DDI-CDI ProcessingAgent should specify at least one activity it performs" ;
                    sh:minCount 1 ;
                    sh:or ( [ sh:nodeKind sh:IRI ] [ sh:nodeKind sh:BlankNode ] ) ;
                    sh:path cdi:performs ;
                    sh:severity sh:Warning ] ;
            sh:value 42 ] .

@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms true .
